// 🧭 FACTUM — ETL com cálculo de bolsa

const map = {
  'MATRICULA': 'MATRICULA',
  'NOME ALUNO': 'NOME DO ALUNO',
  'CURSO': 'CURSO',
  'CPF': 'CPF',
  'DATA NASCIMENTO': 'DATANASCIMENTO',
  'ENDEREÇO': 'ENDERECO',
  'CIDADE': 'CIDADE',
  'CEP': 'CEP',
  'ESTADO': 'ESTADO',
  'TELEFONE': 'TELEFONE',
  'CELULAR': 'CELULAR',
  'RESPONSÁVEL': 'RESPONSAVEL FINANCEIRO',
  'REFERENCIA': 'REFERENCIA',
  'DATA VENCIMENTO': 'DATA VCT° PARCELA',
  'VALOR NOMINAL': 'VALOR NOMINAL',
  'VALOR DE BOLSA': 'VALOR DE BOLSA',
  'EMAIL': 'E-MAIL'
};

// normalização
const normalize = str => str ? str.toString().trim().toLowerCase() : '';

// auxiliares
const limparEndereco = texto =>
  texto ? texto.toString().replace(/[.,;:]/g, '').trim() : '';

const limparEmail = email =>
  email ? email.toString().replace(/['"]/g, '').trim() : '';

const formatarCPF = valor => {
  if (!valor) return '="00000000000"';
  const num = valor.toString().replace(/\D/g, '').trim();
  return `="${num.padStart(11, '0').slice(-11)}"`;
};

const formatarData = data => {
  if (!data) return '';

  const s = data.toString().trim();

  if (/^\d{8}$/.test(s)) return s;

  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s)) {
    const [dia, mes, ano] = s.split('/');
    return `${ano}${mes.padStart(2, '0')}${dia.padStart(2, '0')}`;
  }

  const d = new Date(s);
  if (isNaN(d)) return '';
  return `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
};

const formatarValor = valor => {
  if (valor === null || valor === undefined || valor === '') {
    return '="0,00"';
  }

  let num = parseFloat(
    valor
      .toString()
      .replace(',', '.')
      .replace(/[^\d.-]/g, '')
  );

  if (isNaN(num)) num = 0;

  return `="${num.toFixed(2).replace('.', ',')}"`;
};

// leitura
let inputData = $input.all().map(i => i.json);

if (inputData.length === 1 && Array.isArray(inputData[0].data)) {
  inputData = inputData[0].data;
}

// normalizar headers reais da planilha
const headers = {};
if (inputData.length) {
  Object.keys(inputData[0]).forEach(k => {
    headers[normalize(k)] = k;
  });
}

// helper para pegar valor por nome lógico da coluna
const getRowValue = (row, columnName) => {
  const realKey = headers[normalize(columnName)];
  return realKey ? row[realKey] ?? '' : '';
};

// processamento
const output = inputData.map(row => {
  const novo = {};

  for (const [saida, entrada] of Object.entries(map)) {
    let valor = '';

    if (entrada) {
      valor = getRowValue(row, entrada);
    }

    switch (saida) {
      case 'ENDEREÇO':
        valor = limparEndereco(valor);
        break;

      case 'CPF':
        valor = formatarCPF(valor);
        break;

      case 'DATA VENCIMENTO':
        valor = formatarData(valor);
        break;

      case 'VALOR NOMINAL':
      case 'VALOR DE BOLSA':
        valor = formatarValor(valor);
        break;

      case 'EMAIL':
        valor = limparEmail(valor);
        break;
    }

    novo[saida] = valor;
  }

  // cálculo correto: VALOR NOMINAL - VALOR DE BOLSA
  const nominal = parseFloat(
    getRowValue(row, 'VALOR NOMINAL')
      .toString()
      .replace(',', '.')
      .replace(/[^\d.-]/g, '')
  ) || 0;

  const bolsa = parseFloat(
    getRowValue(row, 'VALOR DE BOLSA')
      .toString()
      .replace(',', '.')
      .replace(/[^\d.-]/g, '')
  ) || 0;

  let liquido = nominal - bolsa;
  if (liquido < 0) liquido = 0;

  const valorLiquido = `="${liquido.toFixed(2).replace('.', ',')}"`;

  // ordenação final
  const ordenado = {};
  for (const key of Object.keys(novo)) {
    ordenado[key] = novo[key];

    if (key === 'EMAIL') {
      ordenado[''] = '';
      ordenado['INADIMPLENCIA MENOS BOLSAS'] = valorLiquido;
    }
  }

  return { json: ordenado };
});

return output;
